import{_ as i,l as E,o as e,c as n,v as r,p as s,x as o,d,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"QE 与前瞻指引","description":"","frontmatter":{"title":"QE 与前瞻指引","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/qe-forward-guidance.md","filePath":"econ/qe-forward-guidance.md","lastUpdated":1789023840000}'),h={name:"econ/qe-forward-guidance.md"};function B(c,a,m,A,u,_){const t=E("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="qe-与前瞻指引" tabindex="-1">QE 与前瞻指引 <a class="header-anchor" href="#qe-与前瞻指引" aria-label="Permalink to &quot;QE 与前瞻指引&quot;">​</a></h1><div class="epigraph"><p>下限上能改欧拉的，是未来实际利率路径与名义锚；资产负债表是一条通道，话是另一条——二者都不是把零下限再讲一遍。</p><footer>—— Eggertsson and Woodford, Brookings 2003；Krishnamurthy 对大规模资产购买渠道的分解</footer></div><p><a href="/econ/fg-puzzle">上一课</a>（前瞻指引之谜）。已经把工具写成 \\(\\max\\{i^{\\mathrm{Taylor}},i_{\\mathrm{ELB}}\\}\\)，并指出真正起作用的是对未来路径的承诺。本课的缺口是把非常规拆成两件不同的家具：<strong>前瞻指引</strong>（话：状态依存的利率路径）与 <strong>QE</strong>（资产负债表：久期、信用、流动性）。不重写现金为何给出下限，也不发明某一次购买的基点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>动态 IS 在 \\(i\\) 卡住时，能降的只剩 \\(\\mathbb{E}\\sum\\) 未来实际利率，或抬 \\(\\mathbb{E}\\pi\\)。Eggertsson 与 Woodford 的最优是：承诺在下限结束后保持更低更久，并让价格水平回到目标路径。那是话。QE 改变的是央行持有的久期与信用风险，把公众的长期债换成准备金。Krishnamurthy 一类分解问：若预期不变，这只是资产互换；若改变期限溢价、信用利差或被读成对路径的信号，才进 IS。缺口是分开「表」与「话」，避免把资产规模当成松紧的充分统计。</p><p>零下限课已经说明工具为何卡住。本课不重写现金的名义回报，只把非常规拆成两件家具。财政乘数下一课才问 \\(G\\)；FTPL 再下一课才问盈余现值。这里停在：同样 \\(i=0\\)，话与表不是同一导数。</p><p><span class="marginnote">信号渠道把 QE 读成前瞻指引的可见承诺，于是表与话不是加性的两套魔法。政策评估必须声明市场读到的是哪一条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前瞻指引：把 \\(i\\) 的路径写成状态依存（「直到通胀与缺口满足…」），以降低 \\(\\mathbb{E}r\\)。价格水平目标或平均通胀目标把过去的偏低通胀记入未来超调，正是承诺在下限上的延伸。时间不一致在此翻转：复苏后央行又想立刻回到低通胀、拒绝超调，则话不被信，下限更长。</p><p>QE：在相同的 \\(i=0\\) 上改变相对供给。渠道包括——久期提取（压缩期限溢价）、信用与流动性（若买的是有摩擦的券）、再平衡、以及信号。弹性价格且完全市场时，公众的债券换成准备金接近中性；摩擦与分割使部分券的收益率可被相对供给移动。本课不把 CIP 基差当操作成本；市场层平价见 <code>/quant/irp</code>。</p>',10)),(e(),s(p,null,{default:o(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ELB%5B%22i%20%E5%B7%B2%E5%9C%A8%E4%B8%8B%E9%99%90%22%5D%20--%3E%20FG%5B%22%E5%89%8D%E7%9E%BB%EF%BC%9A%E8%B7%AF%E5%BE%84%E4%B8%8E%E5%90%8D%E4%B9%89%E9%94%9A%22%5D%0A%20%20ELB%20--%3E%20QE%5B%22QE%EF%BC%9A%E8%B5%84%E4%BA%A7%E8%B4%9F%E5%80%BA%E8%A1%A8%22%5D%0A%20%20FG%20--%3E%20EU%5B%22%E6%AC%A7%E6%8B%89%E9%87%8C%E7%9A%84%20E%20r%22%5D%0A%20%20QE%20--%3E%20SIG%5B%22%E8%8B%A5%E8%A2%AB%E8%AF%BB%E6%88%90%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20QE%20--%3E%20HAB%5B%22%E8%8B%A5%E6%94%B9%E5%8F%98%E6%9C%9F%E9%99%90%20%2F%20%E4%BF%A1%E7%94%A8%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20SIG%20--%3E%20EU%0A%20%20HAB%20--%3E%20EU%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>卢卡斯批判：若公众认为表会在复苏后被立刻对冲、话会在复苏后作废，则当前扩张几乎不进 \\(\\mathbb{E}\\pi\\)。Krugman 的暂时货币是同一句。</p><h3 id="表不是第四种中性" tabindex="-1">表不是第四种中性 <a class="header-anchor" href="#表不是第四种中性" aria-label="Permalink to &quot;表不是第四种中性&quot;">​</a></h3><p>长期中性仍在：离开下限、价格灵活，多出来的 \\(H\\) 仍要进 \\(P\\) 或被回笼。非常规改变的是下限持续期内的预期与溢价路径，不是否认数量论的长期。铸币税在 \\(i=0\\) 时流量小；目的是抬 \\(\\mathbb{E}\\pi\\) 与缺口，不是为财政抽税。若市场把它读成货币化，通道串到财政主导，下一课的下一课才是 FTPL。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>话直接改 \\(\\mathbb{E}i\\) 与 \\(\\mathbb{E}\\pi\\)，从而改欧拉。表在无摩擦时改不了相对价格；有偏好栖息或中介约束时，长期债供给下降可以压期限溢价，投资的 \\(q\\) 与抵押约束跟动。把二者混成「印钞」会漏掉：同等规模的 QE，若沟通是「一回到正利率就收」，效应接近资产互换；若沟通是价格水平路径，表是话的可见抵押。</p><p>状态依存的指引（「直到通胀回目标」）比日历指引更接近承诺：日历日期一到，再优化的诱惑立刻回来。Eggertsson–Woodford 要的是价格水平路径，不是某一天必须加息。Krishnamurthy 强调购买哪一类券决定渠道：国债久期、MBS 信用、还是被读成财政货币化。渠道声明清楚，才不会把所有资产负债表扩张写成同一乘数。</p><p><span class="marginnote">有效下限可以略负，逻辑不变：当期 \\(i\\) 的边际已切断，比较的仍是路径与表。本课不讨论加密资产当负利率技术。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估某一次 LSAP 的基点，不写外汇微观结构。开放下 QE 还经汇率外溢，蒙代尔再碰。财政乘数是下一课：下限上货币换不来同样的实际利率路径时，\\(G\\) 的导数往往更大。也不要把 CIP 基差当 QE 的操作成本清单；市场层平价仍在 <code>/quant/irp</code>。</p><p>话与表可以互相读取：大规模购买若被当成「不会立刻收回」，等于把价格水平路径写进资产负债表。反过来，只有话、表不动，承诺的可见抵押更弱。评估必须声明市场读到哪一条，不能把资产规模当充分统计。</p><p>后课默认：下限上先分清路径承诺与资产负债表；评估必须说市场读到哪条通道。下一课：财政扩张在下限上的乘数，以及李嘉图是否把它抵消。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前瞻指引改未来 \\(i\\) 与名义锚；QE 改表，效应依赖摩擦与信号。</li><li>二者都不是把下限机制重讲一遍。</li><li>复苏后拒绝超调，是下限上的时间不一致。</li><li>资产规模不是松紧的充分统计。</li><li>状态依存指引比日历日期更接近承诺。</li><li>出处：Eggertsson and Woodford, Brookings 2003；Krishnamurthy 对 QE 渠道的分解。</li></ul>',13))])}const g=i(h,[["render",B]]);export{f as __pageData,g as default};
